11:*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:#101c2a;color:var(--ink);font-family:ui-rounded,"Trebuchet MS",system-ui,sans-serif}body{background:radial-gradient(ellipse at 50% -18%,#315269 0,transparent 58%),linear-gradient(180deg,#172b3b,#101c2a 76%);overflow-x:hidden}.app{width:min(1120px,100%);margin:0 auto;padding:18px 22px 24px}.topline{height:42px;display:flex;align-items:center;justify-content:space-between;margin-bottom:12px}.brand{display:flex;align-items:center;gap:10px;font-weight:800;letter-spacing:.02em;font-size:15px}.brandmark{width:34px;height:34px;border-radius:12px;background:linear-gradient(145deg,#d9f6b2,#81c99d);display:grid;place-items:center;color:#23483f;box-shadow:0 5px 20px #91dbac40;font-size:19px}.topnote{font-size:12px;color:#b5c9c7;letter-spacing:.1em;text-transform:uppercase}.game-heading{display:flex;align-items:flex-end;justify-content:space-between;margin:0 2px 12px}.eyebrow{font-size:11px;text-transform:uppercase;letter-spacing:.19em;color:#a6d9bd;font-weight:750;margin:0 0 5px}.game-heading h1{font-size:clamp(23px,4vw,36px);line-height:1;margin:0;letter-spacing:-.04em}.game-heading p{margin:8px 0 0;color:#a9bcba;font-size:13px}.session-chip{display:flex;align-items:center;gap:8px;color:#d9e8d9;font-size:12px;background:#ffffff0b;border:1px solid #ffffff16;border-radius:99px;padding:8px 12px}.live-dot{width:7px;height:7px;border-radius:50%;background:#a9e49c;box-shadow:0 0 9px #a9e49c}.game-shell{position:relative;background:#172b3b;border:1px solid #ffffff20;border-radius:22px;overflow:hidden;box-shadow:0 22px 65px #030b1290,inset 0 1px #ffffff12}.canvas-wrap{position:relative;aspect-ratio:16/9;width:100%;background:#405f70}canvas{width:100%;height:100%;display:block;touch-action:none}.hud{position:absolute;inset:15px 16px auto;display:flex;justify-content:space-between;align-items:flex-start;pointer-events:none;z-index:2}.hud-group{display:flex;gap:8px}.hud-card{min-width:82px;padding:8px 11px;background:#122536d9;border:1px solid #d5efdc29;border-radius:12px;box-shadow:0 4px 14px #06111b4a;backdrop-filter:blur(8px)}.hud-label{font-size:9px;letter-spacing:.16em;text-transform:uppercase;color:#b4ccc5;font-weight:800}.hud-value{font-size:16px;line-height:1.2;font-weight:800;margin-top:3px}.hud-value em{font-size:11px;color:#b5ccc0;font-style:normal;font-weight:600}.pause-button{pointer-events:auto;border:1px solid #d5efdc35;border-radius:12px;background:#122536d9;color:#eff8ed;font:inherit;width:40px;height:40px;cursor:pointer;font-size:15px}.pause-button:hover{background:#203d4e}.overlay{position:absolute;inset:0;z-index:3;display:grid;place-items:center;padding:20px;background:linear-gradient(90deg,#0d1b28a8,#0d1b284d,#0d1b28a8);text-align:center}.overlay[hidden]{display:none}.dialog{width:min(390px,92%);padding:24px 24px 20px;border:1px solid #def2d632;border-radius:22px;background:linear-gradient(145deg,#203a48f2,#142938f5);box-shadow:0 20px 50px #06111b80;backdrop-filter:blur(12px)}.dialog-kicker{font-size:10px;letter-spacing:.22em;text-transform:uppercase;color:#c6e8aa;font-weight:800}.dialog h2{font-size:clamp(27px,5vw,39px);line-height:1.02;letter-spacing:-.05em;margin:10px 0 9px}.dialog p{font-size:13px;color:#c2d2ce;line-height:1.55;margin:0 auto 17px;max-width:310px}.primary{border:0;border-radius:12px;padding:12px 20px;background:linear-gradient(180deg,#d6f4a8,#a8df9c);color:#1b3d38;font:800 14px inherit;cursor:pointer;box-shadow:0 6px 18px #98dc9b38;transition:transform .15s,filter .15s}.primary:hover{transform:translateY(-2px);filter:brightness(1.06)}.dialog small{display:block;color:#9eb8b4;font-size:11px;margin-top:13px}.below{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:13px 3px 0}.objective{display:flex;align-items:center;gap:10px;color:#c8d8d2;font-size:12px}.objective-icon{font-size:19px}.objective strong{color:#f3e5a5}.controls-hint{color:#a7bcba;font-size:11px;text-align:right}.touch-controls{display:none;align-items:center;justify-content:space-between;padding:12px 5px 0;user-select:none;-webkit-user-select:none;touch-action:none}.touch-cluster{display:flex;gap:10px}.touch-btn{width:58px;height:54px;border-radius:16px;border:1px solid #d6f1dc32;background:linear-gradient(180deg,#284352,#1b3241);color:#eff7e9;box-shadow:0 5px 14px #07121a66,inset 0 1px #ffffff12;font:700 19px inherit;display:grid;place-items:center;touch-action:none}.touch-btn:active,.touch-btn.pressed{background:#426356;transform:translateY(1px)}.touch-btn.jump{width:74px;color:#183d37;background:linear-gradient(180deg,#d6f4a8,#a8df9c);font-size:13px;letter-spacing:.05em}.footer{display:flex;justify-content:space-between;color:#78918f;font-size:10px;padding:15px 3px 0;letter-spacing:.03em}.footer span:last-child{color:#9bb5ad}@media(max-width:640px){.app{padding:10px 12px 16px}.topline{margin-bottom:8px;height:34px}.brand{font-size:13px}.brandmark{width:30px;height:30px}.topnote{font-size:9px}.game-heading{margin-bottom:9px}.game-heading p{font-size:11px;margin-top:5px}.session-chip{font-size:10px;padding:7px 9px}.game-shell{border-radius:16px}.hud{inset:8px 8px auto}.hud-card{min-width:62px;padding:6px 8px;border-radius:9px}.hud-label{font-size:7px}.hud-value{font-size:12px}.pause-button{width:32px;height:32px;border-radius:9px}.overlay{padding:10px}.dialog{padding:15px 16px 13px;border-radius:17px}.dialog h2{font-size:25px;margin:6px 0}.dialog p{font-size:11px;line-height:1.35;margin-bottom:11px}.primary{padding:10px 16px;font-size:12px}.dialog small{font-size:9px;margin-top:8px}.below{padding-top:9px}.objective{font-size:10px;gap:6px}.objective-icon{font-size:15px}.controls-hint{font-size:9px}.touch-controls{display:flex;padding-top:10px}.touch-btn{width:54px;height:48px;border-radius:14px}.touch-btn.jump{width:68px}.footer{padding-top:10px;font-size:9px}}
